const parse = c => { const m = c.match(/[\d.]+/g).map(Number); return {r:m[0],g:m[1],b:m[2],a:m[3]===undefined?1:m[3]}; };
const lum = ({r,g,b}) => { const f = v => { v/=255; return v<=0.03928? v/12.92 : Math.pow((v+0.055)/1.055,2.4); }; return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b); };
const bgOf = el => { let e = el; while (e) { const c = parse(getComputedStyle(e).backgroundColor); if (c.a > 0.9) return c; if (getComputedStyle(e).backgroundImage !== 'none') return null; e = e.parentElement; } return {r:255,g:255,b:255,a:1}; };
const out = [];
const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
const seen = new Set();
while (walker.nextNode()) { const t = walker.currentNode; if (!t.textContent.trim()) continue; const el = t.parentElement; if (seen.has(el)) continue; seen.add(el); const cs = getComputedStyle(el); const b = el.getBoundingClientRect(); if (b.width < 2 || cs.visibility==='hidden' || el.closest('.sr-only') ) continue; let hidden=false; for (let e=el;e;e=e.parentElement){ if (getComputedStyle(e).display==='none' || getComputedStyle(e).opacity==='0') {hidden=true;break;} } if (hidden) continue; let fg = parse(cs.color); const bg = bgOf(el); if (!bg) { out.push({txt:t.textContent.trim().slice(0,30), note:'bgimage'}); continue; } if (fg.a<1) fg = {r: fg.r*fg.a+bg.r*(1-fg.a), g: fg.g*fg.a+bg.g*(1-fg.a), b: fg.b*fg.a+bg.b*(1-fg.a)}; const L1=lum(fg), L2=lum(bg); const ratio=(Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05); out.push({txt:t.textContent.trim().slice(0,30), cls: el.className && String(el.className).slice(0,30), tag: el.tagName, fs: cs.fontSize, fw: cs.fontWeight, ratio: Math.round(ratio*100)/100, fg: cs.color, bg: `rgb(${bg.r},${bg.g},${bg.b})`}); }
return out.filter(o => o.note || o.ratio < 4.6 || parseFloat(o.fs) < 13);
}"}

